import json
import os
from datetime import datetime


DATA_FILE = "polls.json"


def load_polls():
    if os.path.exists(DATA_FILE):
        with open(DATA_FILE, "r") as f:
            return json.load(f)
    return {}


def save_polls(polls):
    with open(DATA_FILE, "w") as f:
        json.dump(polls, f, indent=2)


def create_poll(polls):
    question = input("Enter the poll question: ").strip()
    if not question:
        print("Question cannot be empty.")
        return

    options = []
    print("Enter options one by one (empty line to finish):")
    while True:
        option = input(f"  Option {len(options) + 1}: ").strip()
        if not option:
            break
        options.append(option)

    if len(options) < 2:
        print("A poll needs at least 2 options.")
        return

    poll_id = str(len(polls) + 1)
    polls[poll_id] = {
        "question": question,
        "options": {opt: 0 for opt in options},
        "voters": [],
        "created": datetime.now().isoformat(),
    }
    save_polls(polls)
    print(f'Poll created with ID: {poll_id}')


def vote(polls):
    list_polls(polls)
    if not polls:
        return

    poll_id = input("Enter poll ID to vote on: ").strip()
    if poll_id not in polls:
        print("Invalid poll ID.")
        return

    voter = input("Enter your name: ").strip()
    if not voter:
        print("Name cannot be empty.")
        return

    if voter in polls[poll_id]["voters"]:
        print("You have already voted on this poll.")
        return

    poll = polls[poll_id]
    print(f'\nQuestion: {poll["question"]}')
    options = list(poll["options"].keys())
    for i, opt in enumerate(options, 1):
        print(f"  {i}. {opt}")

    choice = input("Enter option number: ").strip()
    if not choice.isdigit() or int(choice) < 1 or int(choice) > len(options):
        print("Invalid choice.")
        return

    selected = options[int(choice) - 1]
    poll["options"][selected] += 1
    poll["voters"].append(voter)
    save_polls(polls)
    print(f'Your vote for "{selected}" has been recorded.')


def show_results(polls):
    list_polls(polls)
    if not polls:
        return

    poll_id = input("Enter poll ID to view results: ").strip()
    if poll_id not in polls:
        print("Invalid poll ID.")
        return

    poll = polls[poll_id]
    total = sum(poll["options"].values())
    print(f'\nQuestion: {poll["question"]}')
    print(f"Total votes: {total}")
    print("-" * 40)

    for option, count in poll["options"].items():
        pct = (count / total * 100) if total > 0 else 0
        bar = "█" * int(pct // 5)
        print(f"  {option}: {count} votes ({pct:.1f}%) {bar}")


def list_polls(polls):
    if not polls:
        print("No polls available.")
        return
    print("\nAvailable Polls:")
    print("-" * 40)
    for pid, poll in polls.items():
        total = sum(poll["options"].values())
        print(f"  [{pid}] {poll['question']} ({total} votes)")
    print()


def main():
    polls = load_polls()

    actions = {
        "1": ("Create a poll", create_poll),
        "2": ("Vote on a poll", vote),
        "3": ("View results", show_results),
        "4": ("List all polls", list_polls),
    }

    while True:
        print("\n=== Voting System ===")
        for key, (label, _) in actions.items():
            print(f"  {key}. {label}")
        print("  5. Exit")

        choice = input("\nChoose an action: ").strip()

        if choice == "5":
            print("Goodbye!")
            break
        elif choice in actions:
            actions[choice][1](polls)
        else:
            print("Invalid choice, try again.")


if __name__ == "__main__":
    main()
